#include "models/financial_records.h"
#include <string.h>

static char *copy(const char *s){return g_strdup(s);}
static GPtrArray *copy_array(const GPtrArray *a){GPtrArray*r=g_ptr_array_new_with_free_func(g_free);
 if(a){for(guint i=0;i<a->len;i++)g_ptr_array_add(r,g_strdup(g_ptr_array_index((GPtrArray*)a,i)));}return r;}
gboolean financial_record_identifier_valid(const char*v){return v&&v[0]&&strlen(v)<=128;}
gboolean financial_record_utc_valid(const char*v){return v&&strlen(v)==20&&v[4]=='-'&&v[7]=='-'&&v[10]=='T'&&v[13]==':'&&v[16]==':'&&v[19]=='Z';}
gboolean financial_record_sha256_valid(const char*v){if(!v||strlen(v)!=64)return FALSE;for(guint i=0;i<64;i++)if(!g_ascii_isdigit(v[i])&&(v[i]<'a'||v[i]>'f'))return FALSE;return TRUE;}
gboolean financial_record_amount_valid(const char*v){if(!v||!v[0]||strlen(v)>128)return FALSE;gboolean dot=FALSE;guint before=0,after=0;
 for(const char*p=v;*p;p++){if(*p=='.'&&!dot&&before>0){dot=TRUE;continue;}if(!g_ascii_isdigit(*p))return FALSE;if(dot)after++;else before++;}return before>0&&(!dot||after>0);}
#define S(dst,src,field) (dst)->field=copy((src)->field)
