BankProposalRecord *bank_proposal_record_copy(const BankProposalRecord*s){if(!s||!financial_record_identifier_valid(s->id)||!financial_record_identifier_valid(s->investigation_id)||!financial_record_identifier_valid(s->evidence_id)||s->end_offset<s->start_offset||s->origin<0||s->origin>BANK_ORIGIN_HUMAN||!financial_record_utc_valid(s->created_at)||!s->observation_ids||s->observation_ids->len>256)return NULL;BankProposalRecord*r=g_new0(BankProposalRecord,1);S(r,s,id);S(r,s,investigation_id);S(r,s,evidence_id);S(r,s,created_at);r->start_offset=s->start_offset;r->end_offset=s->end_offset;r->ambiguous=s->ambiguous;r->origin=s->origin;r->observation_ids=copy_array(s->observation_ids);r->roles=copy_array(s->roles);r->reasons=copy_array(s->reasons);return r;}
