BankAccountRecord *bank_account_record_copy(const BankAccountRecord*s){if(!s||!financial_record_identifier_valid(s->entity_id)||!financial_record_identifier_valid(s->investigation_id)||!s->iban_normalized||!s->country_code||s->state<0||s->state>BANK_ACCOUNT_STATE_CLOSED||!financial_record_utc_valid(s->first_observed_at)||!financial_record_utc_valid(s->last_observed_at))return NULL;BankAccountRecord*r=g_new0(BankAccountRecord,1);S(r,s,entity_id);S(r,s,investigation_id);S(r,s,iban_normalized);S(r,s,country_code);S(r,s,bank_code);S(r,s,branch_code);S(r,s,account_number);S(r,s,rib_key);S(r,s,bic);S(r,s,declared_institution);S(r,s,first_observed_at);S(r,s,last_observed_at);S(r,s,factual_notes);r->state=s->state;return r;}
